do $$ declare f text; begin select pg_get_functiondef(p.oid) into f from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='complete_production' and pg_get_function_identity_arguments(p.oid)='p_production_batch_id uuid, p_consumptions jsonb, p_outputs jsonb'; if f is null then raise exception 'complete_production function not found'; end if; f:=replace(f,' if v_planned is not null and v_output_total>v_planned+0.000001 then raise exception ''Actual production output cannot exceed planned output''; end if;',' -- Actual output is an observation used by the yield-learning model; it may be above or below the estimate.'); execute f; end $$;
